import{_ as e,o,c as t,a2 as c}from"./chunks/framework.C2mit3tn.js";const f=JSON.parse('{"title":"外观","description":"","frontmatter":{},"headers":[],"relativePath":"zh/api/appearance.md","filePath":"zh/api/appearance.md","lastUpdated":1789196459000}'),r={name:"zh/api/appearance.md"};function a(i,d,l,n,s,p){return o(),t("div",null,[...d[0]||(d[0]=[c('<h1 id="外观" tabindex="-1">外观 <a class="header-anchor" href="#外观" aria-label="Permalink to &quot;外观&quot;">​</a></h1><p>把 <code>theme</code>、<code>settings</code> 传给 <code>SweetEditor</code>，或在就绪后调用 <code>applyTheme</code> / <code>setSettings</code>。</p><p>颜色是打包的 ARGB <code>Int</code>（<code>0xAARRGGBB</code>）。大于 <code>0x7FFFFFFF</code> 的字面量要 <code>.toInt()</code>。</p><h2 id="editorsettings" tabindex="-1">EditorSettings <a class="header-anchor" href="#editorsettings" aria-label="Permalink to &quot;EditorSettings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>wrapMode</code></td><td><code>NONE</code></td><td><code>CHAR_BREAK</code>、<code>WORD_BREAK</code></td></tr><tr><td><code>tabSize</code></td><td><code>4</code></td><td></td></tr><tr><td><code>insertSpaces</code></td><td><code>true</code></td><td></td></tr><tr><td><code>lineSpacingAdd</code></td><td><code>0f</code></td><td>额外像素</td></tr><tr><td><code>lineSpacingMult</code></td><td><code>1.2f</code></td><td></td></tr><tr><td><code>scale</code></td><td><code>1f</code></td><td>视觉缩放初值</td></tr><tr><td><code>fontSizeSp</code></td><td><code>14f</code></td><td></td></tr><tr><td><code>readOnly</code></td><td><code>false</code></td><td></td></tr><tr><td><code>gutterVisible</code></td><td><code>true</code></td><td></td></tr><tr><td><code>gutterSticky</code></td><td>平台默认</td><td>粘性行号</td></tr><tr><td><code>currentLineRenderMode</code></td><td><code>BACKGROUND</code></td><td><code>BORDER</code>、<code>NONE</code></td></tr><tr><td><code>foldArrowMode</code></td><td><code>ALWAYS</code></td><td><code>AUTO</code>、<code>HIDDEN</code></td></tr><tr><td><code>renderWhitespace</code></td><td><code>NONE</code></td><td><code>BOUNDARY</code>、<code>SELECTION</code>、<code>TRAILING</code>、<code>ALL</code></td></tr><tr><td><code>renderLineBreaks</code></td><td><code>false</code></td><td></td></tr><tr><td><code>autoIndentMode</code></td><td><code>KEEP_INDENT</code></td><td>或 <code>NONE</code></td></tr><tr><td><code>backspaceUnindent</code></td><td><code>true</code></td><td></td></tr><tr><td><code>decorationOverscanViewportMultiplier</code></td><td><code>1f</code></td><td>Provider 额外视口</td></tr><tr><td><code>decorationScrollRefreshMinIntervalMs</code></td><td><code>50</code></td><td>节流</td></tr></tbody></table><h2 id="editortheme" tabindex="-1">EditorTheme <a class="header-anchor" href="#editortheme" aria-label="Permalink to &quot;EditorTheme&quot;">​</a></h2><p><code>EditorTheme.dark()</code> 即默认构造。<code>EditorTheme.light()</code> 是浅色预设。</p><p>常见分组：</p><ul><li>表面：<code>backgroundColor</code>、<code>textColor</code>、<code>cursorColor</code>、<code>currentLineColor</code></li><li>行号区：<code>lineNumberColor</code>、<code>currentLineNumberColor</code>、<code>splitLineColor</code>、<code>gutterIconColor</code></li><li>滚动条：<code>scrollbarTrackColor</code>、<code>scrollbarThumbColor</code>、<code>scrollbarThumbActiveColor</code></li><li>选区 / 链接 / CodeLens / 搜索 / 诊断 / 高亮 / 联动编辑 / 括号</li><li>Diff：<code>diffAdded*</code> / <code>diffRemoved*</code></li><li>菜单与内联建议条</li><li><code>fontFamily</code>（默认 <code>FontFamily.Monospace</code>）</li><li><code>rangeEffects: EditorRangeEffects?</code> — 按区间覆盖</li></ul><p><code>EditorRangeEffectStyle</code> 含 <code>foregroundColor</code>、<code>backgroundColor</code>、<code>borderColor</code>、<code>underlineColor</code>、<code>underlineStyle</code>（<code>NONE</code>、<code>SOLID</code>、<code>DASHED</code>、<code>WAVY</code>）。</p><p><code>rangeEffects</code> 为 null 时，主题颜色字段会自动映射（选区背景、波浪诊断、实线 IME 下划线等）。</p>',11)])])}const u=e(r,[["render",a]]);export{f as __pageData,u as default};
